// ============================================
// ETAPA 2: PREPARAR PAYLOAD - GENERATE BACKGROUND
// Usa o prompt gerado para criar imagem nova
// ============================================

const input = $input.first().json;

// Dados da etapa anterior
const generatedPrompt = input.generatedPrompt;
const base64Image = input.originalImage?.base64 || '';
const mimeType = input.originalImage?.mimeType || 'image/png';
const sceneType = input.sceneType || 'unknown';

console.log('=== ETAPA 2: GENERATE BACKGROUND ===');
console.log('Scene Type:', sceneType);
console.log('Generated Prompt length:', generatedPrompt?.length || 0);
console.log('Base64 length:', base64Image?.length || 0);

// 🔒 VALIDAÇÕES CRÍTICAS (OBRIGATÓRIAS)
if (!base64Image || base64Image.length < 100) {
  throw new Error('Imagem base64 inválida ou vazia (Generate Image)');
}

if (!generatedPrompt || generatedPrompt.length < 20) {
  throw new Error('Prompt inválido para geração de imagem');
}

// ============================================
// PROMPT ESTRUTURADO COMPLETO
// ============================================
const fullPrompt = `Create a photorealistic commercial product photograph.

PRODUCT REFERENCE GUIDE:
- Use the product from the reference image as your visual guide for the product's identity
- MAINTAIN product IDENTITY: preserve exact colors, design, brand elements, key features
- You MAY FREELY ADJUST: angle, position, scale, perspective, lighting to fit the scene naturally
- The product should look NATURALLY INTEGRATED in the new scene, NOT "cut and pasted"
- Allow creative composition - reposition and rescale the product as needed

SCENE TO CREATE:
${generatedPrompt}

CREATIVE FREEDOM:
- Reposition and rescale product naturally for the scene
- Use realistic lighting that matches the environment
- Product can be shown from different angles if it fits better
- Create depth and natural integration between product and scene
- Make it look like an actual professional photo, not a composite

STRICTLY FORBIDDEN: text, letters, words, watermarks, logos that weren't in original product

OUTPUT: Generate a single high-quality product photograph showing the product in the described scene.`;

console.log('Full prompt length:', fullPrompt.length);

// ============================================
// PAYLOAD PARA GEMINI IMAGE GENERATION
// ============================================
const payload = {
  contents: [
    {
      parts: [
        {
          inlineData: {
            mimeType,
            data: base64Image
          }
        },
        {
          text: fullPrompt
        }
      ]
    }
  ],
  generationConfig: {
    responseModalities: ['image', 'text'],
    temperature: 0.4,
    candidateCount: 1
  }
};

// ✅ PROPAGA TUDO PARA O PRÓXIMO NÓ
return {
  json: {
    payload,
    generatedPrompt,
    originalImage: input.originalImage,
    sceneType
  }
};

// ============================================
// ETAPA 1: PREPARAR PAYLOAD PARA GERAR PROMPT
// Gemini vai ANALISAR a imagem e CRIAR um prompt
// Template: AMBIENT_2 (Lifestyle)
// ============================================

// ✅ PEGAR DADOS DO INPUT (ORDEM CORRETA!)
const items = $input.all();
const raw = items[0]?.json;

// 🔹 Converter string do Redis em objeto
const item =
  typeof raw.job === 'string'
    ? JSON.parse(raw.job)
    : raw.job || raw;

// ✅ AGORA SIM pode usar "item"
const sceneType = item.variant_type || '';

// ✅ IMAGEM VEM DE payload.images OU images direto
const base64Image = item.payload?.images?.[0]?.base64 || item.images?.[0]?.base64 || '';
const mimeType =
  item.payload?.images?.[0]?.mimeType ||
  item.payload?.images?.[0]?.mime_type ||
  item.images?.[0]?.mimeType ||
  'image/png';

if (!base64Image) {
  throw new Error('Imagem base64 não encontrada');
}

console.log('=== ETAPA 1: GENERATE PROMPT (AMBIENT_2 - LIFESTYLE) ===');
console.log('Base64 length:', base64Image.length);
console.log('Scene Type:', sceneType);

// Prompt LIFESTYLE para análise do produto
const analyzePrompt = `You are a professional product photographer and creative director.

TASK: Analyze the product in this image and create a LIFESTYLE scene prompt.

SCENE TYPE: LIFESTYLE (ambient_2)

ANALYZE PRODUCT: category, characteristics, target audience, lifestyle context.

CREATE LIFESTYLE SCENE (max 120 words):

- Location and usage context relevant to product type

- People's actions appropriate for this product

- Emotional atmosphere matching target audience

PRESERVE EXACT PRODUCT - only change BACKGROUND.

NO text or writing. Format: Direct prompt.

OUTPUT FORMAT:

Return ONLY the prompt text, no explanations. The prompt should be 2-4 sentences describing a lifestyle scene with this exact product.

Example output format:

"Professional lifestyle photograph of [product] being used by a young professional in a modern apartment living room, warm afternoon light through large windows, relaxed weekend atmosphere, product naturally integrated into daily routine, shot from natural eye-level angle."`;

// Payload para API Gemini
const payload = {
  contents: [
    {
      parts: [
        {
          inlineData: {
            mimeType: mimeType,
            data: base64Image
          }
        },
        {
          text: analyzePrompt
        }
      ]
    }
  ],
  generationConfig: {
    temperature: 0.7,
    candidateCount: 1,
    maxOutputTokens: 1024
  }
};

return {
  json: {
    payload,
    originalImage: {
      base64: base64Image,
      mimeType
    },
    sceneType
  }
};

// ============================================
// ETAPA 2: EXTRAIR PROMPT GERADO DO GEMINI
// ============================================

const items = $input.all();
const geminiResponse = items[0]?.json;

// 🔹 Extrair o prompt gerado da resposta do Gemini
const generatedPrompt = 
  geminiResponse?.candidates?.[0]?.content?.parts?.[0]?.text ||
  geminiResponse?.candidates?.[0]?.content?.parts?.find(p => p.text)?.text ||
  '';

if (!generatedPrompt) {
  throw new Error('Prompt não foi gerado pelo Gemini');
}

// 🔹 A imagem original vem do node anterior (passada via originalImage)
// Se o fluxo passa dados entre nodes, buscar de $('NodeAnterior').first().json
const previousData = $('Preparar Payload - Generate Prompt2').first().json;

const base64Image = 
  previousData?.originalImage?.base64 ||
  previousData?.payload?.images?.[0]?.base64 ||
  '';

const mimeType = 
  previousData?.originalImage?.mimeType ||
  'image/png';

const sceneType = previousData?.sceneType || 'ambient_2';

if (!base64Image) {
  throw new Error('Imagem base64 não encontrada no node anterior');
}

