  try {
    contexto = $('code trigger3').first().json;
    if (contexto?.jobId) fonteContexto = 'code trigger';
  } catch (e) {}
}

// Método 3: Redis Pop (dados originais)
if (!contexto?.jobId) {
  try {
    contexto = $('Redis Pop').first().json;
    if (contexto?.jobId) fonteContexto = 'Redis Pop';
  } catch (e) {}
}

