// ETAPA 2: PREPARAR PAYLOAD - GENERATE BACKGROUND
// USA O PROMPT GERADO + IMAGEM DE REFERÊNCIA
// ============================================

const input = $input.first().json;

// ==============================
// DADOS DA ETAPA ANTERIOR
// ==============================
const generatedPrompt = input.generatedPrompt;
const originalImage = input.originalImage;
const sceneType = input.sceneType;
const requestId = input.requestId;

// ==============================
// VALIDAÇÕES CRÍTICAS
// ==============================
if (!generatedPrompt) {
  throw new Error('generatedPrompt ausente no Worker');
}

if (!originalImage?.base64) {
  throw new Error('originalImage.base64 ausente no Worker');
}

const base64Image = originalImage.base64;
const mimeType = originalImage.mimeType || 'image/png';

console.log('=== ETAPA 2: GENERATE BACKGROUND ===');
console.log('Scene:', sceneType);
console.log('Prompt preview:', generatedPrompt.substring(0, 120));
console.log('Base64 length:', base64Image.length);

// ==============================
// PROMPT ESTRUTURADO (SEU, INTACTO)
// ==============================
const fullPrompt = `Create a photorealistic commercial product photograph.

PRODUCT REFERENCE GUIDE:
- Use the product from the reference image as your visual guide for the product's identity
- MAINTAIN product IDENTITY: preserve exact colors, design, brand elements, key features
- You MAY FREELY ADJUST: angle, position, scale, perspective, lighting to fit the scene naturally
- The product should look NATURALLY INTEGRATED in the new scene, NOT "cut and pasted"
- Allow creative composition - reposition and rescale the product as needed

SCENE TO CREATE:
${generatedPrompt}

CREATIVE FREEDOM:
- Reposition and rescale product naturally for the scene
- Use realistic lighting that matches the environment
- Product can be shown from different angles if it fits better
- Create depth and natural integration between product and scene
- Make it look like an actual professional photo, not a composite

STRICTLY FORBIDDEN: text, letters, words, watermarks, logos that weren't in original product

OUTPUT: Generate a single high-quality product photograph showing the product in the described scene.`;

// ==============================
// PAYLOAD PARA GEMINI IMAGE MODEL
// ==============================
const payload = {
  contents: [
    {
      parts: [
        {
          inlineData: {
            mimeType: mimeType,
            data: base64Image
          }
        },
        {
          text: fullPrompt
        }
      ]
    }
  ],
  generationConfig: {
    responseModalities: ["image"], // 🔴 ESSENCIAL
    temperature: 0.4,
    candidateCount: 1
  }
};

// ==============================
// SAÍDA PADRÃO DO WORKER
// ==============================
return {
  json: {
    payload,
    sceneType,
    requestId
  }
};

// ================================================================
// EXTRAIR PROMPT + PRESERVAR DADOS ORIGINAIS
// ================================================================

// 1) Input do Gemini
const geminiResponse = $input.first().json;

// 2) Extrair o prompt gerado
let generatedPrompt = '';
try {
  if (geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text) {
    generatedPrompt = geminiResponse.candidates[0].content.parts[0].text;
  }
} catch (e) {
  console.log('Erro ao extrair prompt:', e.message);
}

// Fallback
if (!generatedPrompt || generatedPrompt.length < 20) {
  generatedPrompt = 'Professional product photograph in a modern, minimal studio setting with soft natural lighting and clean background.';
}

// ================================================================
// 3) CRÍTICO: Buscar dados do node ANTERIOR para preservar imagem
// ================================================================
const dadosOriginais = $('Preparar Payload ').first().json;
const originalImage = dadosOriginais.originalImage;
const sceneType = dadosOriginais.sceneType || 'ambient_1';
const requestId = dadosOriginais.requestId;
const productName = dadosOriginais.productName;

// 4) Retornar TUDO junto
return {
  json: {
    generatedPrompt: generatedPrompt.trim(),
    originalImage,      // Agora definido!
    sceneType,          // Agora definido!
    requestId,
    productName,
    _debug: {
      temImagem: !!originalImage?.base64,
      promptLength: generatedPrompt.length
    }
  }
};

