try {
  contexto = $node["Preparar Payload "].json;
} catch (e) {}

// Fallback (caso futuro)
if (!contexto?.jobId) {
  try {
    contexto = $node["Redis Pop"].json;
  } catch (e) {}
}

// 2️⃣ Extrair imagem do Gemini
