const raw = $json.propertyName;

if (!raw) {
  return [];
}

const job = typeof raw === 'string' ? JSON.parse(raw) : raw;

return [{
  json: {
    jobId: job.jobId,
    type: job.type,
    prompt: job.prompt,
    payload: job
  }
}];

// ============================================
// ETAPA 1: PREPARAR PAYLOAD PARA GERAR PROMPT
// Gemini ANALISA a imagem e CRIA um prompt
// COMPATÍVEL COM REDIS + WEBHOOK + LOVABLE
// ============================================

const items = $input.all();
let data = items[0]?.json || {};

// ------------------------------------------------
// NORMALIZAR INPUT (Redis envia job como string)
// ------------------------------------------------
if (typeof data.job === 'string') {
  try {
    data = JSON.parse(data.job);
  } catch (e) {
    throw new Error('Falha ao fazer parse do job JSON');
  }
}

// payload real pode estar em payload ou body
let payload = data.payload || data.body || data;

// ------------------------------------------------
// EXTRAIR IMAGEM (ÚNICO PONTO CRÍTICO)
// ------------------------------------------------
let base64Image = '';
let mimeType = 'image/png';

if (payload.images && Array.isArray(payload.images) && payload.images[0]) {
  base64Image = payload.images[0].base64 || '';
  mimeType = payload.images[0].mimeType || 'image/png';
}

// Remover prefixo data:image/... se existir
if (base64Image.startsWith('data:')) {
  base64Image = base64Image.split(',')[1];
}

// VALIDAR IMAGEM
if (!base64Image || base64Image.length < 100) {
  throw new Error('Imagem base64 não encontrada ou inválida');
}

// ------------------------------------------------
// SCENE TYPE
// ------------------------------------------------
const sceneType =
  payload.sceneType ||
  payload.variant_type ||
  'ambient_1';

// ------------------------------------------------
// PROMPT ORIGINAL (NÃO ALTERADO)
// ------------------------------------------------
const analyzePrompt = `You are a professional product photographer and creative director.

TASK: Analyze the product in this image and create a detailed prompt for generating a professional product photograph.

SCENE TYPE REQUESTED: ${sceneType}

Based on this scene type, create a detailed, specific prompt that describes:
1. The ideal environment/setting for this product
2. Lighting conditions (natural, studio, warm, cool, etc.)
3. Props and contextual elements that complement the product
4. Mood and atmosphere
5. Camera angle and composition suggestions

OUTPUT FORMAT:
Return ONLY the prompt text, no explanations. The prompt should be 2-4 sentences, highly descriptive and specific for this exact product.

Example output format:
"Professional photograph of [product] on a marble kitchen countertop with morning sunlight streaming through a window, surrounded by fresh herbs and copper utensils, warm and inviting atmosphere, shot from a 45-degree angle."`;

// ------------------------------------------------
// PAYLOAD PARA GEMINI
// ------------------------------------------------
const geminiPayload = {
  contents: [
    {
      parts: [
        {
          inlineData: {
            mimeType,
            data: base64Image
          }
        },
        {
          text: analyzePrompt
        }
      ]
    }
  ],
  generationConfig: {
    temperature: 0.7,
    candidateCount: 1,
    maxOutputTokens: 1024
  }
};

// ------------------------------------------------
// SAÍDA PADRÃO (NUNCA QUEBRA O FLUXO)
// ------------------------------------------------
return {
  json: {
    payload: geminiPayload,
    originalImage: {
      base64: base64Image,
      mimeType
    },
    sceneType
  }
};

